#include <stdio.h>

static int clamp(int value, int low, int high) {
    return value < low ? low : (value > high ? high : value);
}

int main(void) {
    int failed = 0;
    if (clamp(12, 0, 10) != 10) ++failed;
    if (clamp(-1, 0, 10) != 0) ++failed;
    printf("%s\n", failed ? "failed" : "all checks passed");
    return failed ? 1 : 0;
}
